"""Personal profile contract additions, executed by build-openapi.py."""
profile_bool = {'type': 'boolean'}
S['PersonalProfileUser'] = obj({**fieldnames('id name email avatar_url'), 'phone': {'anyOf': [string(), {'type': 'null'}]}, 'role': string(enum=['admin', 'operator', 'viewer'])}, ['id', 'name', 'email', 'phone', 'avatar_url', 'role'])
S['PersonalProfile'] = obj({'user': ref('PersonalProfileUser'), 'departments': arr(obj(fieldnames('id name'), ['id', 'name'])), 'permissions': obj({k: profile_bool for k in ['view', 'investigate', 'approve', 'execute', 'manage']}, ['view', 'investigate', 'approve', 'execute', 'manage']), 'applications': arr(obj({**fieldnames('id key name'), 'permission': string(enum=['view', 'operate'])}, ['id', 'key', 'name', 'permission'])), 'can_change_password': profile_bool}, ['user', 'departments', 'permissions', 'applications', 'can_change_password'])
route('get', '/profile', 'Read own profile, departments and effective application permissions', response=ref('PersonalProfile'), desc='Current authenticated identity only. Departments reuse stable team memberships. Applications include direct and department grants with viewer/archived operate caps. Capability flags summarize effective access; execution still requires approved plans. Phone is nullable and read-only.')
route('patch', '/profile', 'Replace or remove own avatar', body=obj({'avatar_data_url': string(maxLength=1398136)}, ['avatar_data_url']), response=ref('PersonalProfile'), desc='Only avatar_data_url may be changed. Empty string removes avatar. Strict PNG/JPEG base64, input up to 1 MiB, dimensions up to 1024x1024 and 1048576 pixels. Image is decoded and reencoded as PNG, discarding metadata. Canonical stored PNG is bounded to 4 MiB. Avatar content never enters audit records.')
route('post', '/profile/password', 'Change own local password and revoke all own sessions', body=obj({'current_password': string(minLength=1, maxLength=1024), 'new_password': string(minLength=8, maxLength=128)}, ['current_password', 'new_password']), status=204, desc='Requires current password and a different new password. New passwords contain 8–128 Unicode characters and require ASCII uppercase and lowercase letters, ASCII digits, and at least one Unicode punctuation or symbol character; invalid values return 422 invalid_password. Existing password input retains the 1024-byte login cap, without applying new password complexity rules. Directory source is metadata, not SSO: any active identity with a valid local password hash may change it. No configured local password returns 422 no_local_password. Wrong current password returns 422 incorrect_password, preserving the session. Successful hash update, all-user-session revocation and secret-free audit are transactional; response expires the current cookie. A new login is required.')
